/// <reference lib="webworker" />

import { parsePatchFiles, type FileDiffMetadata } from "@pierre/diffs"

type ParsePatchWorkerRequest = {
  id: number
  patchText: string
  cacheKeyPrefix: string
}

type ParsePatchWorkerResponse = {
  id: number
  files: FileDiffMetadata[]
  parseError: string
}

const getErrorMessage = (value: unknown) => {
  if (typeof value === "string") {
    return value
  }
  if (value && typeof value === "object" && "message" in value) {
    return String((value as { message?: string }).message)
  }
  return "Unable to parse merge request diff."
}

self.addEventListener("message", (event: MessageEvent<ParsePatchWorkerRequest>) => {
  const { id, patchText, cacheKeyPrefix } = event.data

  if (!patchText) {
    const response: ParsePatchWorkerResponse = {
      id,
      files: [],
      parseError: "",
    }
    self.postMessage(response)
    return
  }

  try {
    const patches = parsePatchFiles(patchText, cacheKeyPrefix)
    const files = patches.flatMap((patch) => patch.files)

    const response: ParsePatchWorkerResponse = {
      id,
      files,
      parseError: "",
    }
    self.postMessage(response)
  } catch (error) {
    const response: ParsePatchWorkerResponse = {
      id,
      files: [],
      parseError: getErrorMessage(error),
    }
    self.postMessage(response)
  }
})

export {}

export async function POST(request: Request) {
  const headerStorePromise = headers()
  const payloadPromise = request.json().catch(() => null)
  const sessionPromise = headerStorePromise.then((headerStore) =>
    auth.api.getSession({ headers: headerStore }),
  )

  const [session, payloadValue] = await Promise.all([sessionPromise, payloadPromise])

  if (!session?.user?.id) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
  }

  const payload = payloadValue as TrackEventPayload | null
  if (!payload || !isOnboardingEvent(payload.event)) {
    return NextResponse.json({ error: "Invalid onboarding event." }, { status: 400 })
  }

  const metadata =
    payload.metadata && typeof payload.metadata === "object"
      ? payload.metadata
      : undefined

  void db
    .insert(onboardingEvents)
    .values({
      userId: session.user.id,
      event: payload.event,
      metadata,
    })
    .catch(() => null)

  return NextResponse.json({ ok: true })
}

