const formatShortcutLabel = (shortcut?: PaletteShortcut) => {
  if (!shortcut) {
    return undefined
  }

  const tokens: string[] = []
  if (shortcut.mod) {
    tokens.push("⌘")
  }
  if (shortcut.shift) {
    tokens.push("⇧")
  }
  if (shortcut.alt) {
    tokens.push("⌥")
  }
  tokens.push(shortcut.key.toUpperCase())

  return tokens.join("+")
}

const doesShortcutMatch = (
  event: globalThis.KeyboardEvent,
  shortcut: PaletteShortcut,
) => {
  if (event.key.toLowerCase() !== shortcut.key.toLowerCase()) {
    return false
  }
  if (shortcut.mod) {
    if (!event.metaKey && !event.ctrlKey) {
      return false
    }
  } else if (event.metaKey || event.ctrlKey) {
    return false
  }
  if (Boolean(shortcut.shift) !== event.shiftKey) {
    return false
  }
  if (Boolean(shortcut.alt) !== event.altKey) {
    return false
  }
  return true
}

export function CommandPalette() {
  const router = useRouter()
  const pathname = usePathname()
  const [isOpen, setIsOpen] = useState(false)

  const commands = useMemo(
    () => COMMANDS.filter((command) => !command.href || command.href !== pathname),
    [pathname],
  )

  const groupedCommands = useMemo(() => {
    const grouped: Record<PaletteCommand["group"], PaletteCommand[]> = {
      Navigation: [],
      Onboarding: [],
      Tools: [],
    }

    for (const command of commands) {
      grouped[command.group].push(command)
    }

    return grouped
  }, [commands])

  const runCommand = useCallback(
    (command: PaletteCommand) => {
      if (command.href) {
        router.push(command.href)
      } else {
        command.action?.()
      }
      setIsOpen(false)
    },
    [router],
  )

const renderCommandGroup = React.useCallback(
  (group: keyof typeof groupedCommands) => {
    const items = groupedCommands[group]
    if (items.length === 0) {
      return null
    }

    return (
      <CommandGroup key={group} heading={group}>
        {items.map((command) => (
          <CommandItem
            key={command.id}
            value={`${command.id} ${command.label} ${command.description}`}
            onSelect={() => runCommand(command)}
            className="gap-2"
          >
            <command.icon />
            <span>{command.label}</span>
            {command.shortcut ? (
              <CommandShortcut>{formatShortcutLabel(command.shortcut)}</CommandShortcut>
            ) : null}
          </CommandItem>
        ))}
      </CommandGroup>
    )
  },
  [groupedCommands, runCommand],
)

const handleCommandKeyDown = React.useCallback(
  (event: React.KeyboardEvent) => {
    if (!isOpen) {
      return
    }

    if (!(event.key.length === 1) && !["Escape", "ArrowDown", "ArrowUp", "Enter"].includes(event.key)) {
      return
    }

    const target = event.target as EventTarget | null
    if (!(target instanceof Element)) {
      return
    }

    const command = commands.find(
      (candidate) =>
        candidate.shortcut ? doesShortcutMatch(event.nativeEvent, candidate.shortcut) : false,
    )

    if (!command) {
      return
    }

    event.preventDefault()
    runCommand(command)
  },
  [commands, isOpen, runCommand],
)

useEffect(() => {
  const isTextInput = (element: EventTarget | null) => {
    if (!(element instanceof HTMLElement)) {
      return false
    }

    const tagName = element.tagName.toLowerCase()
    return (
      tagName === "input" ||
      tagName === "textarea" ||
      element.isContentEditable
    )
  }

  const handleGlobalShortcut = (event: KeyboardEvent) => {
    if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
      if (isTextInput(event.target)) {
        return
      }
      event.preventDefault()
      setIsOpen((current) => !current)
    }
  }

  window.addEventListener("keydown", handleGlobalShortcut)
  return () => window.removeEventListener("keydown", handleGlobalShortcut)
}, [])

