  const [activeTab, setActiveTab] = useState("gitlab")
  const [tokens, setTokens] = useState<SavedTokens>(() => readSavedTokensFromStorage())
  const [gitlabStatus, setGitlabStatus] = useState("")
  const [aiSettings, setAiSettings] = useState<AISettings>(() => readAiSettingsFromStorage())
  const [aiStatus, setAiStatus] = useState("")
  const [themeMode, setThemeMode] = useState<ThemeMode>(() => readThemeModeFromStorage())
  const [themeStatus, setThemeStatus] = useState("")
  const { setTheme } = useTheme()
  const gitlabAutoSaveTimer = useRef<number | null>(null)
  const aiAutoSaveTimer = useRef<number | null>(null)
