const hasInitializedAiAutoSave = useRef(false)
const hasInitializedThemeAutoSave = useRef(false)

useEffect(() => {
  setTheme(getActualThemeMode(themeMode))
}, [setTheme, themeMode])

const handleTokenChange = (key: GitlabInstanceKey, value: string) => {
  setTokens((current) => ({
    ...current,
    [key]: value,
  }))
}

const handleAiSettingChange = (
  key: keyof AISettings,
  value: string,
) => {
  setAiSettings((current) => ({
    ...current,
    [key]: value,
  }))
}

const clearStatusLater = (setStatus: (value: string) => void) => {
  window.setTimeout(() => {
    setStatus("")
  }, 2000)
}

const clearTokens = () => {
  setTokens(emptyTokens)
  setGitlabStatus("GitLab tokens cleared.")
  clearStatusLater(setGitlabStatus)
}

const clearAISettings = () => {
  setAiSettings(emptyAiSettings)
  setAiStatus("AI settings cleared.")
  clearStatusLater(setAiStatus)
}

const handleThemeModeChange = (value: ThemeMode) => {
  setThemeMode(value)
}

useEffect(() => {
  if (!hasInitializedGitlabAutoSave.current) {
    hasInitializedGitlabAutoSave.current = true
    return
  }
  if (gitlabAutoSaveTimer.current) {
    window.clearTimeout(gitlabAutoSaveTimer.current)
    gitlabAutoSaveTimer.current = null
  }
  gitlabAutoSaveTimer.current = window.setTimeout(() => {
    if (typeof window !== "undefined") {
      window.localStorage.setItem(GITLAB_STORAGE_KEY, JSON.stringify(tokens))
      setGitlabStatus("GitLab changes auto-saved.")
      clearStatusLater(setGitlabStatus)
    }
    gitlabAutoSaveTimer.current = null
  }, SETTINGS_AUTOSAVE_DEBOUNCE_MS)

  return () => {
    if (gitlabAutoSaveTimer.current) {
      window.clearTimeout(gitlabAutoSaveTimer.current)
      gitlabAutoSaveTimer.current = null
    }
  }
}, [tokens])

useEffect(() => {
  if (!hasInitializedAiAutoSave.current) {
    hasInitializedAiAutoSave.current = true
    return
  }
  if (aiAutoSaveTimer.current) {
    window.clearTimeout(aiAutoSaveTimer.current)
    aiAutoSaveTimer.current = null
  }
  aiAutoSaveTimer.current = window.setTimeout(() => {
    if (typeof window !== "undefined") {
      window.localStorage.setItem(AI_SETTINGS_STORAGE_KEY, JSON.stringify(aiSettings))
      setAiStatus("AI settings auto-saved.")
      clearStatusLater(setAiStatus)
    }
    aiAutoSaveTimer.current = null
  }, SETTINGS_AUTOSAVE_DEBOUNCE_MS)

  return () => {
    if (aiAutoSaveTimer.current) {
      window.clearTimeout(aiAutoSaveTimer.current)
      aiAutoSaveTimer.current = null
    }
  }
}, [aiSettings])

useEffect(() => {
  if (!hasInitializedThemeAutoSave.current) {
    hasInitializedThemeAutoSave.current = true
    return
  }
  if (themeAutoSaveTimer.current) {
    window.clearTimeout(themeAutoSaveTimer.current)
    themeAutoSaveTimer.current = null
  }
  themeAutoSaveTimer.current = window.setTimeout(() => {
    if (typeof window !== "undefined") {
      window.localStorage.setItem(THEME_SETTINGS_STORAGE_KEY, themeMode)
      setThemeStatus("Theme preference auto-saved.")
      clearStatusLater(setThemeStatus)
    }
    themeAutoSaveTimer.current = null
  }, SETTINGS_AUTOSAVE_DEBOUNCE_MS)

  return () => {
    if (themeAutoSaveTimer.current) {
      window.clearTimeout(themeAutoSaveTimer.current)
      themeAutoSaveTimer.current = null
    }
  }
}, [themeMode])

useEffect(() => {
  if (themeMode !== "argus") {
    return
  }

  const mediaQuery = window.matchMedia("(prefers-color-scheme: dark)")
  const handleSystemThemeChange = () => {
    setTheme(getActualThemeMode("argus"))
  }
  mediaQuery.addEventListener("change", handleSystemThemeChange)

  return () => {
    mediaQuery.removeEventListener("change", handleSystemThemeChange)
  }
}, [themeMode, setTheme])

return (
  <div className="space-y-4">
    <section className="space-y-1">
      <h1 className="text-2xl font-semibold">Settings</h1>
      <p className="text-sm text-muted-foreground">
        Configure GitLab tokens per deployment.
      </p>
    </section>

