  }
  return hashTokenForCache(trimmed)
}, [token])
const projectsCacheKey = useMemo(() => {
  if (!tokenCacheHash) {
    return ""
  }

  try {
    const normalizedInstance = resolveGitLabInstance(gitlabInstance, customInstance)
    return `${normalizedInstance}::${tokenCacheHash}`
  } catch {
    return ""
  }
}, [tokenCacheHash, gitlabInstance, customInstance])

const trackEvent = (
  event:
    | "onboarding_started"
    | "onboarding_token_validated"
    | "onboarding_projects_selected"
    | "onboarding_completed",
  metadata?: OnboardingEventMetadata,
) => {
  const body = JSON.stringify({ event, metadata })

  if (typeof navigator !== "undefined" && typeof navigator.sendBeacon === "function") {
    try {
      const sent = navigator.sendBeacon(
        "/api/onboarding/track",
        new Blob([body], { type: "application/json" }),
      )
      if (sent) {
        return
      }
    } catch {
    }
  }

  void fetch("/api/onboarding/track", {
    method: "POST",
    headers: {
      "content-type": "application/json",
    },
    body,
    keepalive: true,
  }).catch(() => null)
}

const getErrorMessage = (value: unknown) => {
  if (typeof value === "string") {
    return value
  }
  if (value && typeof value === "object" && "error" in value) {
    return String((value as { error?: string }).error)
  }
  return "Something went wrong."
}

const callGitLab = useCallback(async (
  action: "projects" | "merge-requests",
  options?: { projectId?: string; perPage?: number },
) => {
  const normalizedInstance = resolveGitLabInstance(gitlabInstance, customInstance)
  const response = await fetch("/api/gitlab", {
    method: "POST",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify({
      action,
      instanceUrl: normalizedInstance,
      token,
      ...(options?.projectId ? { projectId: options.projectId } : {}),
      ...(typeof options?.perPage === "number" ? { perPage: options.perPage } : {}),
    }),
  })

  const payload = await response.json()
  if (!response.ok) {
    throw new Error(getErrorMessage(payload))
  }

  if (!Array.isArray(payload.data)) {
    throw new Error("Unexpected response from server.")
  }

  return payload.data
}, [gitlabInstance, customInstance, token])

const projectsQueryKey = useCallback(
  () => ["onboarding", "projects", projectsCacheKey] as const,
  [projectsCacheKey],
)
const mergeRequestsQueryKey = useCallback(
  (projectId: string, perPage: number) =>
    ["onboarding", "merge-requests", projectsCacheKey, projectId, perPage] as const,
  [projectsCacheKey],
)

const applyLoadedProjects = (data: Project[]) => {
  setProjects(data)
  setSelectedProjectId("")
  setMergeRequests([])
  setSelectedMergeRequestId("")
}

const fetchMergeRequests = useCallback(async (
  projectId: string,
  { perPage = MERGE_REQUESTS_FULL_LIMIT }: { perPage?: number } = {},
) => {
  const normalizedPerPage = Math.min(
    MERGE_REQUESTS_FULL_LIMIT,
    Math.max(1, Math.floor(perPage)),
  )
  if (!projectsCacheKey) {
    throw new Error("Personal access token is required.")
  }

  const queryKey = mergeRequestsQueryKey(projectId, normalizedPerPage)
  const cached = queryClient.getQueryData<MergeRequest[]>(queryKey)
  if (cached !== undefined) {
    return cached
  }

  return queryClient.fetchQuery({
    queryKey,
    queryFn: () =>
      callGitLab("merge-requests", {
        projectId,
        perPage: normalizedPerPage,
      }) as Promise<MergeRequest[]>,
    staleTime: ONBOARDING_QUERY_STALE_TIME,
    gcTime: ONBOARDING_QUERY_GC_TIME,
  })
}, [callGitLab, mergeRequestsQueryKey, projectsCacheKey, queryClient])

const fetchProjects = async ({ force = false }: { force?: boolean } = {}) => {
  if (!projectsCacheKey) {
    throw new Error("Personal access token is required.")
  }

  if (force) {
    await queryClient.invalidateQueries({ queryKey: projectsQueryKey(), exact: true })
  }

  return queryClient.fetchQuery({
    queryKey: projectsQueryKey(),
    queryFn: () => callGitLab("projects") as Promise<Project[]>,
    staleTime: ONBOARDING_QUERY_STALE_TIME,
    gcTime: ONBOARDING_QUERY_GC_TIME,
  })
}

useEffect(() => {
