  }

  if (previousProjectsCacheKeyRef.current === null) {
    previousProjectsCacheKeyRef.current = projectsCacheKey
    return
  }

  if (previousProjectsCacheKeyRef.current === projectsCacheKey) {
    return
  }

  previousProjectsCacheKeyRef.current = projectsCacheKey
  void queryClient.removeQueries({ queryKey: ONBOARDING_QUERY_KEY_PREFIX })
