  const preloadedCacheKey = mergeRequestsQueryKey(projectId, MERGE_REQUESTS_PRELOAD_LIMIT)
  const cachedFullMergeRequests = queryClient.getQueryData<MergeRequest[]>(fullCacheKey)
  const cachedPreloadedMergeRequests = queryClient.getQueryData<MergeRequest[]>(preloadedCacheKey)

  if (cachedFullMergeRequests !== undefined) {
    setMergeRequests(cachedFullMergeRequests)
    router.push("/onboarding/mrs")
    void trackEvent("onboarding_projects_selected", {
      selectedProjectCount: projects.length,
      projectId,
