  }

  startedEventTracked.current = true
  void trackEvent("onboarding_started")
}, [isHydrated, routeStep])

useEffect(() => {
  setTokenTestFeedback(null)
}, [token, gitlabInstance, customInstance])

useEffect(() => {
  if (!isHydrated) {
    return
  }

  if (routeStep === "projects" && !token.trim()) {
    router.replace("/onboarding/tokens")
    return
  }

  if (routeStep === "mrs" && !selectedProjectId) {
    router.replace("/onboarding/projects")
  }
}, [isHydrated, routeStep, token, selectedProjectId, router])

useEffect(() => {
  if (!isHydrated || routeStep !== "projects" || !projectsCacheKey || projects.length === 0) {
    return
  }

  const projectIds = projects
    .slice(0, MERGE_REQUESTS_PRELOAD_PROJECTS_LIMIT)
    .map((project) => project.id)
  let cancelled = false

  const preloadMergeRequests = async () => {
    const workerCount = Math.min(MERGE_REQUESTS_PRELOAD_CONCURRENCY, projectIds.length)
    let nextProjectIndex = 0

    const workers = Array.from({ length: workerCount }, () => async () => {
      while (!cancelled) {
        const projectId = projectIds[nextProjectIndex]
        nextProjectIndex += 1

        if (!projectId) {
          return
        }

        await queryClient
          .prefetchQuery({
            queryKey: mergeRequestsQueryKey(projectId, MERGE_REQUESTS_PRELOAD_LIMIT),
            queryFn: () =>
              callGitLab("merge-requests", {
                projectId,
                perPage: MERGE_REQUESTS_PRELOAD_LIMIT,
              }) as Promise<MergeRequest[]>,
            staleTime: ONBOARDING_PREFETCH_STALE_TIME,
            gcTime: ONBOARDING_QUERY_GC_TIME,
          })
          .catch(() => null)
      }
    })

    await Promise.allSettled(workers.map((worker) => worker()))
  }

  void preloadMergeRequests()

  return () => {
    cancelled = true
  }
}, [
  callGitLab,
  isHydrated,
  mergeRequestsQueryKey,
  projects,
  projectsCacheKey,
  queryClient,
  routeStep,
])

useEffect(() => {
  if (
    !isHydrated ||
    actionBusy ||
    (routeStep !== "projects" && routeStep !== "mrs") ||
    (routeStep === "projects" && recentProjects.length === 0) ||
    (routeStep === "mrs" && mergeRequests.length === 0)
  ) {
    return
  }

  const onKeyDown = (event: KeyboardEvent) => {
    if (
      event.defaultPrevented ||
      event.metaKey ||
      event.ctrlKey ||
      event.altKey ||
      event.repeat
    ) {
      return
    }

    const target = event.target as HTMLElement | null
    if (
      target &&
      (target.tagName === "INPUT" ||
        target.tagName === "TEXTAREA" ||
        target.tagName === "SELECT" ||
        target.isContentEditable)
    ) {
      return
    }

    if (!/^[0-9]$/.test(event.key)) {
      return
    }

    const index = event.key === "0" ? RECENT_PROJECTS_LIMIT - 1 : Number(event.key) - 1
    if (routeStep === "projects") {
      const project = recentProjects[index]
      if (!project) {
        return
      }

      event.preventDefault()
      void projectSelectionHandlerRef.current?.(project.id)
      return
    }

    const mergeRequest = mergeRequests[index]
    if (!mergeRequest) {
      return
    }
    event.preventDefault()
    mergeRequestSelectionHandlerRef.current?.(mergeRequest.id)
  }

  window.addEventListener("keydown", onKeyDown)
  return () => window.removeEventListener("keydown", onKeyDown)
}, [isHydrated, routeStep, actionBusy, recentProjects, mergeRequests])

if (routeStep === "tokens") {
  return (
    <OnboardingTokenStep
      currentStep={currentStep}
      instancePresets={INSTANCE_PRESETS}
      gitlabInstance={gitlabInstance}
      customInstance={customInstance}
      token={token}
      tokenTestFeedback={tokenTestFeedback}
      projectsError={projectsError}
      canLoadProjects={canLoadProjects}
      actionBusy={actionBusy}
      tokenTestBusy={tokenTestBusy}
      onGitlabInstanceChange={setGitlabInstance}
      onCustomInstanceChange={setCustomInstance}
      onTokenChange={setToken}
      onSubmit={handleTokenSubmit}
      onTestToken={testToken}
      onPrefetchContinue={preloadProjectsForContinue}
    />
  )
}

if (routeStep === "projects") {
  return (
    <OnboardingProjectsStep
      currentStep={currentStep}
      canLoadProjects={canLoadProjects}
      actionBusy={actionBusy}
      hasProjects={projects.length > 0}
      selectedProjectId={selectedProjectId}
      projectSearchQuery={projectSearchQuery}
      normalizedProjectSearchQuery={normalizedProjectSearchQuery}
      recentProjects={recentProjects}
      projectsError={projectsError}
      mergeRequestsError={mergeRequestsError}
      shortcutLimit={RECENT_PROJECTS_LIMIT}
      onSearchChange={setProjectSearchQuery}
      onBackToTokens={() => router.push("/onboarding/tokens")}
      onReloadProjects={() => void loadProjects({ force: true })}
      onProjectSelect={(projectId) => void handleProjectSelection(projectId)}
      onPrefetchContinue={preloadProjectsForContinue}
    />
  )
}

  return (
    <OnboardingMergeRequestsStep
      currentStep={currentStep}
      selectedProject={selectedProject}
      selectedMergeRequest={selectedMergeRequest}
      selectedMergeRequestId={selectedMergeRequestId}
      mergeRequests={mergeRequests}
      resolvedGitLabInstance={resolvedGitLabInstance}
      token={token}
      actionBusy={actionBusy}
      mergeRequestsError={mergeRequestsError}
      shortcutLimit={RECENT_PROJECTS_LIMIT}
      onBackToProjects={() => router.push("/onboarding/projects")}
      onReloadMergeRequests={() =>
        void (
          selectedProjectId &&
          loadMergeRequests(selectedProjectId, {
            skipNavigation: true,
            skipTracking: true,
            preserveSelection: true,
          })
        )
      }
      onSelectMergeRequest={handleMergeRequestSelection}
    />
  )
}

